use std::{collections::HashSet, path::PathBuf, time::Instant};
use pamin_index::{Rerank, Reranker};
use pamin_engine::{place, score_blend_order, RERANK_FUSION};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("runtime {}", ort::info());
    let args: Vec<_> = std::env::args().collect();
    assert_eq!(args.len(), 7, "input output cache expected_device short_physical_tokens ready_marker");
    let short_physical_tokens: u64 = args[5].parse()?;
    assert!([256, 512].contains(&short_physical_tokens));
    let input = PathBuf::from(&args[1]);
    let output = PathBuf::from(&args[2]);
    let rows: Vec<serde_json::Value> = serde_json::from_slice(&std::fs::read(input)?)?;
    assert_eq!(rows.len(), 1190);
    let ids: HashSet<_> = rows.iter().map(|r| r["id"].as_str().unwrap()).collect();
    assert_eq!(ids.len(), rows.len());
    assert!(rows.iter().all(|r| r["candidates"].as_array().unwrap().len() == 30));
    let load = Instant::now();
    let mut model = Reranker::load(Rerank::Accurate, &PathBuf::from(&args[3]))?;
    let load_seconds = load.elapsed().as_secs_f64();
    assert_eq!(model.device().name(), args[4], "unexpected provider fallback");
    assert_eq!(model.counted().maximum_tokens, 256, "different input truncation contract");
    // Unique queries warm both short and long physical buckets without warming
    // any evaluation pair's score-cache key.
    let long = "database migration rollback ".repeat(300);
    let medium = "database migration rollback ".repeat(20);
    for i in 0..8 {
        let q = format!("measurement warmup {i}: migration failure");
        // Separate calls are essential: batching short + medium together
        // otherwise warms only the 128-token bucket, leaving 64 cold.
        for (document, expected_tokens, interval) in [
            ("a migration rolls back", short_physical_tokens, 1..=64),
            (medium.as_str(), 512, 65..=128),
            (long.as_str(), 512, 129..=256),
        ] {
            let before = model.counted();
            let scored = model.rank(&q, &[document])?;
            let after = model.counted();
            assert!(interval.contains(&(after.tokens - before.tokens)), "warmup did not execute its intended logical-token interval");
            assert_eq!(scored.len(), 1);
            assert!(scored[0].score.is_finite());
            assert_eq!(after.batches - before.batches, 1);
            assert_eq!(after.padded_tokens - before.padded_tokens, expected_tokens,
                       "warmup did not execute the intended physical bucket");
        }
    }
    println!("warmup_complete");
    use std::io::Write as _;
    std::io::stdout().flush()?;
    let ready = PathBuf::from(&args[6]);
    let waiting = Instant::now();
    while !ready.is_file() {
        assert!(waiting.elapsed().as_secs() < 60, "resource inventory did not release the measurement barrier");
        std::thread::sleep(std::time::Duration::from_millis(20));
    }
    let mut results = Vec::with_capacity(rows.len());
    let start = Instant::now();
    for (index, row) in rows.iter().enumerate() {
        let candidates = row["candidates"].as_array().unwrap();
        let docs: Vec<_> = candidates.iter().map(|c| c["shown"].as_str().unwrap()).collect();
        let before = model.counted();
        let timer = Instant::now();
        let ranked = model.rank(row["text"].as_str().unwrap(), &docs)?;
        let seconds = timer.elapsed().as_secs_f64();
        let after = model.counted();
        assert_eq!(ranked.len(), docs.len());
        assert_eq!(after.offered - before.offered, 30);
        let mut scores = vec![f32::NAN; docs.len()];
        for r in ranked { assert!(r.score.is_finite()); assert!(scores[r.position].is_nan()); scores[r.position] = r.score; }
        assert!(scores.iter().all(|v| v.is_finite()));
        let fused: Vec<_> = candidates.iter().map(|c| c["fused"].as_f64().unwrap()).collect();
        let scores64: Vec<_> = scores.iter().map(|&s| f64::from(s)).collect();
        let order = score_blend_order(&fused, &scores64, RERANK_FUSION);
        let topics: Vec<String> = serde_json::from_value(row["topics"].clone())?;
        let shown: Vec<_> = candidates.iter().map(|c| c["position"].as_u64().unwrap() as usize).collect();
        assert!(shown.iter().all(|&i| i < topics.len()));
        let ranking = place(topics, &shown, 30, &order);
        results.push(serde_json::json!({"id":row["id"], "scores":scores, "ranking":ranking,
            "rank_seconds":seconds, "scored":after.scored-before.scored,
            "batches":after.batches-before.batches, "padded_tokens":after.padded_tokens-before.padded_tokens,
            "encode_us":after.encode_us-before.encode_us, "forward_us":after.forward_us-before.forward_us}));
        if (index + 1) % 11 == 0 || index + 1 == rows.len() {
            let value = serde_json::json!({"device":model.device().name(), "maximum_tokens":256,
                "completed_queries":results.len(), "expected_queries":1190, "expected_pairs":35700,
                "complete":results.len()==rows.len(), "load_seconds":load_seconds,
                "wall_seconds":start.elapsed().as_secs_f64(), "warmup_calls":24,
                "shared_machine":true, "whole_product_latency":false,
                "boundary":"Reranker::rank plus product fusion/placement replay on fixed candidates", "rows":results});
            let partial = output.with_extension("partial");
            std::fs::write(&partial, serde_json::to_vec(&value)?)?;
            std::fs::rename(partial, &output)?;
            println!("{} {}/1190", model.device().name(), index + 1);
        }
    }
    assert_eq!(results.len(), 1190);
    Ok(())
}
